public class NormalizerCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Normalizer impl) {
        try {
            return NormalizerChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectNormalizer()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectNormalizer()));
        check("rejects the forgotten lower-casing", false, verdict(new KeepsCaseNormalizer()));
        check("rejects the run of spaces left uncollapsed", false, verdict(new NoCollapseNormalizer()));
        check("rejects the version that deletes spaces instead of collapsing them", false, verdict(new StripsSpacesNormalizer()));
        check("rejects the version that only collapses spaces, not tabs", false, verdict(new TabBlindNormalizer()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectNormalizer implements Normalizer {
    public String normalize(String text) {
        return text.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

class AlsoCorrectNormalizer implements Normalizer {
    public String normalize(String text) {
        String[] words = text.trim().split("\\s+");
        return String.join(" ", words).toLowerCase();
    }
}

class KeepsCaseNormalizer implements Normalizer {
    public String normalize(String text) {
        return text.trim().replaceAll("\\s+", " ");
    }
}

class NoCollapseNormalizer implements Normalizer {
    public String normalize(String text) {
        return text.trim().toLowerCase();
    }
}

class StripsSpacesNormalizer implements Normalizer {
    public String normalize(String text) {
        return text.trim().replace(" ", "").toLowerCase();
    }
}

class TabBlindNormalizer implements Normalizer {
    public String normalize(String text) {
        return text.trim().replaceAll(" +", " ").toLowerCase();
    }
}

