/**
 * TASK: Write the checks that decide whether a Normalizer is correct.
 *
 *   normalize(text) trims the ends, collapses every run of whitespace to a
 *   single space, and lower-cases the result.
 *   Examples: "  Hello   World  " -> "hello world",  "A\tB" -> "a b",
 *             "" -> "",  "Single" -> "single"
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
interface Normalizer {
    /* Provided -- do not edit. */
    String normalize(String text);
}

public class NormalizerChecker {

    public static boolean isCorrect(Normalizer impl) {
        try {
            if (!"hello world".equals(impl.normalize("  Hello   World  "))) return false;
            if (!"a b".equals(impl.normalize("A\tB"))) return false;
            if (!"".equals(impl.normalize(""))) return false;
            if (!"".equals(impl.normalize("   "))) return false;
            if (!"single".equals(impl.normalize("Single"))) return false;
            if (!"one two three".equals(impl.normalize("one  two\n\nthree"))) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
